body.script:
        (function() {
          const params = new URLSearchParams(window.location.search);
          params.set("t", Date.now());
          const targetUrl = "https://cdn.jsdelivr.net/gh/akki5012YT/DroidMoon/webdroid.html?" + params.toString();

          const scriptContent = `

            (function launch() {
              const url = "\${targetUrl}";
              fetch(url)
                .then(r => {
                  if (!r.ok) throw new Error("HTTP " + r.status + " (ファイルが見つかりません)");
                  return r.text();
                })
                .then(html => {
                  document.open();
                  document.write(html);
                  document.close();
                })
                .catch(err => {
                  console.error("DroidMoon Loader Error:", err);
                  document.body.innerHTML = '

DroidMoon 読み込みエラー
' + err.message + '
GitHubリポジトリ (akki5012YT/DroidMoon) に webdroid.html がアップロードされているか確認してください。';
                });
            })();
            <\/script>
          `;

          const theIframe = document.getElementById('test');
          theIframe.srcdoc = scriptContent;
        })();
